import React from 'react';
import './App.css';
import { Provider, useDispatch } from 'react-redux';
import store from './redux/store';
import LoginPage from './pages/auth/login/Login.jsx';
import SignupPage from './pages/auth/signup/Signup.jsx';
import FaceEnroll from './pages/auth/signup/FaceEnroll.jsx';
import FaceVerify from './pages/auth/login/FaceVerify.jsx';
import { setUser, logout } from './redux/authSlice';
import { BrowserRouter as Router, Switch, Route, useHistory, useLocation, Redirect } from 'react-router-dom';

function AppContent() {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();

  const handleLogin = (user) => {
    dispatch(setUser(user));
    history.push('/face-verification');
  };

  const handleLogout = () => {
    dispatch(logout());
    history.push('/login');
  };

  // Helper to parse query params for face-enroll route
  const getQueryParams = () => {
    const searchParams = new URLSearchParams(location.search);
    return {
      reference: searchParams.get('reference'),
      email: searchParams.get('email'),
    };
  };

  const { reference, email } = getQueryParams();

  return (
    <Switch>
      <Route exact path="/" render={() => <Redirect to="/login" />} />
      <Route path="/login" render={() => <LoginPage onLogin={handleLogin} />} />
      <Route path="/signup" render={() =>
        <SignupPage onVerified={(reference, email) => {
          history.push(`/face-enroll?reference=${reference}&email=${encodeURIComponent(email)}`);
        }} />
      } />
      <Route path="/face-enroll" render={() => <FaceEnroll reference={reference} email={email} />} />
      <Route path="/face-verification" render={() => <FaceVerify />} />
    </Switch>
  );
}

function App() {
  return (
    <Provider store={store}>
      <Router>
        <AppContent />
      </Router>
    </Provider>
  );
}

export default App;
